def dot(a, b):
    return sum(x * y for x, y in zip(a, b))

def norm(a):
    return sum(x * x for x in a) ** 0.5

def normalize(a):
    n = norm(a)
    return [x / n for x in a]

def cosine(a, b):
    return dot(a, b) / (norm(a) * norm(b))

a = [3.0, 4.0]
b = [1.0, 0.0]
a_normalized = normalize(a)

print(norm(a))
print(round(norm(a_normalized), 6))
print(dot(a, b))
print(dot(a_normalized, b))
print(round(cosine(a, b), 6))
print(round(cosine(a_normalized, b), 6))

