def dot(a, b):
    return sum(x * y for x, y in zip(a, b))

def euclidean(a, b):
    return sum((x - y) ** 2 for x, y in zip(a, b)) ** 0.5

def cosine_similarity(a, b):
    dot_ab = dot(a, b)
    norm_a = sum(x * x for x in a) ** 0.5
    norm_b = sum(y * y for y in b) ** 0.5
    return dot_ab / (norm_a * norm_b)

a = [2, 0, 1]
b = [1, 1, 1]

print(dot(a, b))
print(round(euclidean(a, b), 4))
print(round(cosine_similarity(a, b), 4))

def dot(a, b):
    return sum(x * y for x, y in zip(a, b))

def norm(a):
    return sum(x * x for x in a) ** 0.5

def cosine_similarity(a, b):
    return dot(a, b) / (norm(a) * norm(b))

query = [1.0, 0.0]
doc_short = [0.95, 0.05]   # nearly perfectly aligned with the query's direction
doc_long = [2.4, 2.4]      # larger magnitude, but only loosely aligned in direction

print(round(dot(query, doc_short), 4))
print(round(dot(query, doc_long), 4))
print(round(cosine_similarity(query, doc_short), 4))
print(round(cosine_similarity(query, doc_long), 4))

def cosine_similarity(a, b):
    dot_ab = sum(x * y for x, y in zip(a, b))
    norm_a = sum(x * x for x in a) ** 0.5
    norm_b = sum(y * y for y in b) ** 0.5
    return dot_ab / (norm_a * norm_b)

def brute_force_knn(query, stored_vectors, k):
    scored = [
        (name, cosine_similarity(query, vec))
        for name, vec in stored_vectors.items()
    ]
    scored.sort(key=lambda pair: pair[1], reverse=True)
    return scored[:k]

stored_vectors = {
    "doc_a": [0.9, 0.1, 0.0],
    "doc_b": [0.1, 0.9, 0.0],
    "doc_c": [0.85, 0.15, 0.05],
    "doc_d": [0.0, 0.0, 1.0],
}

query = [1.0, 0.0, 0.0]
print(brute_force_knn(query, stored_vectors, k=2))

